            locationQuery.isNullOrBlank() ||
                    location.contains(locationQuery, ignoreCase = true)

        val matchesGuestCount =
            guestCount == null ||
                    (guestCount > 0 && guestCount <= maximumOccupancy)

        return matchesLocation && matchesGuestCount
    }


